values
  ('foundation-course-beauty-therapy', 'Foundation Course in Beauty Therapy', 'Beauty Therapy', 'Explore foundational beauty therapy through skin theory, client consultation and practical care procedures.', '360 Hrs', '/beauty-therapy.avif', 'Beauty therapist performing a facial treatment during training', '[{"heading":"Theory of Skin","topics":["Introduction to Skin Science","Skin Anatomy","Structure and Layers of the Skin","Functions of the Skin","Classification of Skin Types"]},{"heading":"Skin Disorders","topics":["Identification of Common Skin Disorders","Basic Understanding of Skin Conditions","Contraindications for Beauty Treatments"]},{"heading":"Theory & Demonstration","topics":["Client Consultation Techniques","Client and Trolley Preparation","Threading Techniques","Pedicure Procedures","Manicure Procedures","Waxing Techniques","Face Clean-Up Procedure","Skin Bleaching Procedure","Facials Procedures","Bed Setup Techniques","Towel Tucking Techniques"]},{"heading":"Sterilization and Sanitization","topics":["Proper Cleaning and Disinfection of Tools, Equipment and Workstations","Hygiene Protocols to Prevent Cross-Contamination and Ensure Client Safety"]},{"heading":"Safety Measures","topics":["Safe Handling of Electrical Machines, Products & Treatment Tools","Following Workplace Safety, Personal Hygiene and Professional Standards"]},{"heading":"Homecare Products","topics":["Recommending Suitable Homecare Products Based on Skin Type and Treatment","Educating Clients on Daily Skin Maintenance and Aftercare Routine"]}]'::jsonb, 10, true),
  ('advance-course-beauty-therapy', 'Advance Course in Beauty Therapy', 'Beauty Therapy', 'Build advanced beauty therapy knowledge across skin treatments, electrotherapy, waxing and hand and foot care.', '240 Hrs', '/advance-course-beauty-therapy.jpg', 'Beauty therapist applying a facial mask during a treatment demonstration', '[{"heading":"Theory of Skin","topics":["Introduction to Skin Science","Skin Anatomy","Structure and Layers of the Skin","Functions of the Skin","Classification of Skin Types"]},{"heading":"Skin Disorders","topics":["Identification of Common Skin Disorders","Basic Understanding of Skin Conditions","Contraindications for Beauty Treatments","International Brand Products Knowledge","Tools & Equipment Knowledge"]},{"heading":"Client Consultation","topics":["Professional Skin Analysis","Treatment Planning Based on Skin Conditions","Client Record Maintenance"]},{"heading":"Post-Care Advice","topics":["Post-Treatment Skin Care Guidelines","Home Care Recommendations for Clients","Product Usage and Maintenance Advice"]},{"heading":"Waxing","topics":["Advanced Liposoluble Wax Techniques","Brazilian Wax Techniques"]},{"heading":"Hand & Foot","topics":["Nail Anatomy","Bones & Muscles of Limbs","Crystal Spa Pedicure","Crystal Spa Manicure","Anti-ageing Pedicure","Anti-ageing Manicure","Hydrating Pedicure","Hydrating Manicure"]},{"heading":"Electro Therapy","topics":["Ultrasonic","Rejuvenating device","Galvanic","High Frequency"]},{"heading":"Facial Treatments","topics":["Under-Eye Treatment","Anti-Ageing Treatment","Anti-Acne Treatment","Anti-Pigmentation Treatment","Anti-Tan Treatment"]},{"heading":"Sterilization and Sanitization","topics":["Proper Cleaning and Disinfection of Tools, equipment and Workstations","Hygiene Protocols to Prevent Cross-Contamination and Ensure Client Safety"]},{"heading":"Salon Management","topics":["Appointment Scheduling and Smooth Service co-ordination","Maintaining Client Records, Product Stock and treatment Planning"]},{"h