  ('foundation-course-hair-dressing', 'Foundation Course in Hair Dressing', 'Hair Dressing', 'Develop foundational hairdressing skills across hair theory, care, cutting, styling and basic colouring.', '360 Hrs', 'https://images.unsplash.com/photo-1562322140-8baeececf3df?auto=format&fit=crop&w=1200&q=85', 'Hair dressing lesson in a salon setting', '[{"heading":"Hair Theory","topics":["Hair Anatomy","Metamorphosis of Hair","Structure of Hair","Hair Types and Texture"]},{"heading":"Client Consultation & Analysis","topics":["Hair and Scalp Analysis","Treatment Planning Based on conditions","Client Record Maintenance"]},{"heading":"Tools and Product Knowledge","topics":[],"note":"No subtopics were listed under this heading in the supplied document."},{"heading":"Hair Care Procedures","topics":["Hair Shampooing & Conditioning treatments","Head Massage"]},{"heading":"Female Haircuts","topics":["Hair Cutting Terminology","Scissor and Comb Handling techniques","One-Length Straight Cut","One-Length U-Cut","One-Length V-Cut","Straight Bob","Bangs and Fringes"]},{"heading":"Male Haircuts","topics":["Barbering - Scissor Over Comb","Basic short - One Finger Depth","Clean Shaving Techniques"]},{"heading":"Hair Styling & Settings","topics":["Blast Dry Techniques","Straight Blow Dry","Thermal Settings"]},{"heading":"Hair Colouring","topics":["Colour Theory","Henna Mixing and Application techniques","Global Hair Colouring (Basic Shades)","Root Touch-Up Techniques"]},{"heading":"Sterilization and Sanitization","topics":["Hygiene standards in Hair Services","Tool and Equipment Disinfection"]},{"heading":"Safety Measures","topics":["Workplace safety Practices","Safe Handling of Hair Tools & Equipment"]},{"heading":"Homecare Products","topics":["Basic Hair Care Products","Homecare Routine for Hair Maintenance","Product Recommendation Guidelines"]}]'::jsonb, 30, true),
  ('advance-course-hair-dressing', 'Advance Course in Hair Dressing', 'Hair Dressing', 'Expand hairdressing practice through advanced cuts, styling, colour, spa and permanent treatments.', '480 Hrs', '/advanced-certificate-hair-dressing-enhanced.png', 'Stylist arranging a detailed updo during a hair dressing lesson', '[{"heading":"Hair Theory","topics":["Hair Anatomy","Metamorphosis of Hair","Structure of Hair","Hair Types and Texture"]},{"heading":"Client Consultation & Analysis","topics":["Hair and Scalp Analysis","Treatment Planning Based on Conditions","Client Record Maintenance","International Brand Products Knowledge","Tools & Equipment Knowledge"]},{"heading":"Advance Female Haircuts","topics":["Long Layers","Short Layers","Graduated Cuts","Creative Layer cuts","Fringes & Bangs"]},{"heading":"Advanced Men''s Haircuts","topics":["Buzz Cut Style","Crew Cut Style","Undercut Haircut","Taper Fade","Low Fade","Mid Fade","French Crop Haircut","Mohawk Haircut Styles"]},{"heading":"Moustache Designing & Beard Care","topics":["French Beard","Goatee Style","Short Boxed Beard","Stubble Beard (Short / Medium)","Full Beard Styling","Winter Beard","Duck Tail Beard"]},{"heading":"Thermal Styling Techniques","topics":["Ironing","Tonging","Crimping","Blow Dry - Curls and Out Curls"]},{"heading":"Hair Spa Treatments","topics":["Product Knowledge","Dandruff treatment","Deep Nourishing treatment"]},{"heading":"Electro Therapy","topics":["High Frequency","Hot Roller"]},{"heading":"Hair Colouring","topics":["Theory of Hair Colour","Colour Application Techniques","Grey Coverage Techniques","Global Fashion Shade Colouring","Pre-Lightening Techniques","Highlighting Techniques","Ombre Techniques","Balayage Techniques"]},{"heading":"Permanent Hair Treatments","topics":["Hair Smoothening","Hair Straightening / Rebonding","Hair Perming","Hair Botox"]},{"heading":"Sterilization and Sanitization","topics":["Hygiene Standards in Hair services","Tool and Equipment Disinfection"]},{"heading":"Salon Management","topics":["Professional Salon Practices","Client Service and Consultation"]},{"heading":"Safety Measures","topics":["Workplace Safety Practices","Safe Handling of Hair Tools & equipment"]},{"heading":"Homecare Products","topics":["Hair Care Products","Homecare Routine for Hair maintenance","Product Recommendation guidelines"]}]'::jsonb, 40, true),
  ('foundation-course-makeup-artistry', 'Foundation Course in Makeup Artistry', 'Makeup Artistry', 'Start in makeup artistry with foundational theory, makeup looks, saree draping and hairstyling.', '240 Hrs', 'https://images.unsplash.com/photo-1516975080664-ed2fc6a32937?auto=format&fit=crop&w=1200&q=85', 'Makeup tools and products arranged for an artistry lesson', '[{"heading":"Introduction to Makeup Artistry","topics":["About the Makeup Industry","Role of a Professional Makeup Artist","Scope and Career Opportunities in Makeup Artistry","Professional Etiquette","Skin Analysis & Skin Preparation","Makeup Brush Theory","Colour Theory","Face Shapes"]},{"heading":"Makeup Environment","topics":["Professional Makeup Room setup","Lighting & Hygiene Standards","Makeup Workspace arrangement","Contraindications & Makeup sequence","Client Consultation"]},{"heading":"Saree Draping","topics":["History of Saree Draping","Importance of Saree Draping for makeup Artists","2 different types of saree draping"]},{"heading":"Sterilization and Sanitization","topics":["Proper Cleaning and Disinfection of Makeup Tools & Work stations","Hygiene Practices to Prevent cross-contamination and Ensure client Safety"]},{"heading":"Safety Measures","topics":["Safe Handling of Makeup products, Electrical Tool & Accessories","Following Personal Hygiene and workplace safety standards"]},{"heading":"Different Types of Makeup Looks","topics":["Day Self Makeup","Corporate Makeup","Party Makeup","Engagement Makeup","Bridal Makeup","Reception Makeup","Groom Makeup"]},{"heading":"Hairstyling","topics":["Hair Styling Basics","Hairstyling Products Knowledge","Tools Used for Hairstyling","Different Types of Hair Upstyles"]},{"heading":"Thermal Styling Techniques","topics":["Ironing","Tonging","Thermal Styling Dos & Don''ts"]},{"heading":"Home care Products","topics":["Recommended skin care and makeup maintenance Products for Clients","Guidance on post-makeup care and product usage at home"]},{"heading":"Freelance Makeup Artist Guidance","topics":["Introduction to freelancing","Essential skills & Kit preparation","Client consultation & Pricing","Marketing & Personal Branding","Professional etiquette & client handling"]}]'::jsonb, 50, true),
